function comparisonRowspans(rows){const spans=Array(rows.length).fill(1);for(let index=0;index<rows.length;){const channel=rows[index].thimble_id,position=String(rows[index].position||'').trim();let end=index+1;if(channel!==null&&channel!==undefined&&channel!==''&&position){while(end<rows.length&&rows[end].thimble_id===channel&&String(rows[end].position||'').trim()===position)end++}if(end-index>1){spans[index]=end-index;for(let continuation=index+1;continuation<end;continuation++)spans[continuation]=0}index=end}return spans}
