function syncCoreAvailability(){const map=$('#coreMap'),unit=$('#unit');if(!map||!unit)return;map.style.pointerEvents=unit.value?'':'none';}
syncCoreAvailability(); $('#unit')?.addEventListener('change',syncCoreAvailability); document.addEventListener('DOMContentLoaded',syncCoreAvailability);

// Keep filter controls synchronized with the latest imported dataset.
const rebuildMainFilters = () => {
  const site = $('#site').value;
  const unit = $('#unit').value;
  const outage = $('#outage').value;
  const available = combinations().filter(item => !site || String(item.site) === String(site));
  const selectedUnit = refill('unit', available.map(item => item.unit_id), '全部机组', unit);
  refill('outage', available.filter(item => !selectedUnit || String(item.unit_id) === String(selectedUnit)).map(item => item.outage), '全部大修', outage);
};
$('#selectServerRoot').onclick=async()=>{if(window.desktopAPI){const path=await window.desktopAPI.selectDirectory();if(path)$('#serverRoot').value=path}else{toast('请在桌面软件中选择服务器目录')}};
$('#scanServerBtn').onclick=async()=>{const root=$('#serverRoot').value.trim(),status=$('#serverStatus'),box=$('#serverSources');if(!root)return toast('请填写服务器根路径');status.textContent='正在连接并识别目录...';box.className='server-sources empty';box.textContent='扫描中，请勿关闭软件';try{const data=await api('/api/discover-server',{method:'POST',body:JSON.stringify({path:root})});status.textContent=`已扫描 ${data.scanned_directories} 个目录，发现 ${data.items.length} 个指套管大修`;box.className='server-sources';box.innerHTML=data.items.length?data.items.map(item=>`<button type="button" data-source="${encodeURIComponent(item.path)}"><b>${item.station||item.site} · ${item.outage}</b><span>${item.project} · ${item.unit_folder||''} · ${item.folder}</span><small>${item.path}</small></button>`).join(''):'<div class="empty">未发现包含 TH 数据组的指套管目录</div>';$$('#serverSources [data-source]').forEach(button=>button.onclick=async()=>{$('#importPath').value=decodeURIComponent(button.dataset.source);$('#importDialog').showModal();$('#reportOptions').className='report-options empty';await scanReportOptions()})}catch(error){status.textContent='连接失败';box.className='server-sources empty';box.textContent=error.message}};









function installReportWorkflow(){
  if($('#reportPreviewDialog'))return;
  const stylesheet=document.createElement('link');stylesheet.rel='stylesheet';stylesheet.href='/report-preview.css?v=20260806a';document.head.append(stylesheet);
  document.body.insertAdjacentHTML('beforeend','<dialog id="reportPreviewDialog" class="report-preview-dialog"><div class="report-preview-head"><div><span>REPORT PREVIEW</span><h2 id="reportPreviewTitle">报告预览</h2></div><button id="closeReportPreview" type="button" aria-label="关闭预览">×</button></div><div id="reportPreviewContent" class="report-preview-content"></div></dialog>');
  $('.export-catalog')?.remove();$('.report-workspace')?.classList.add('report-workspace-single');
  const workspace=$('.report-workspace');
  if(workspace&&!$('#reportModeTabs')){
    workspace.insertAdjacentHTML('beforebegin','<div id="reportModeTabs" class="report-mode-tabs" role="tablist"><button type="button" class="active" data-report-mode="result">结果报告</button><button type="button" data-report-mode="history">历次大修对比</button></div>');
    const comparePanel=$('#comparePanel');
    const setMode=mode=>{
      const result=mode==='result';
      workspace.hidden=!result;
      $('#reportInlinePanel')?.toggleAttribute('hidden',!result);
      if(comparePanel)comparePanel.hidden=result;
      $$('#reportModeTabs [data-report-mode]').forEach(button=>button.classList.toggle('active',button.dataset.reportMode===mode));
    };
    $$('#reportModeTabs [data-report-mode]').forEach(button=>button.addEventListener('click',()=>setMode(button.dataset.reportMode)));
  }
  if(workspace&&!$('#reportInlinePreview'))workspace.insertAdjacentHTML('afterend','<section id="reportInlinePanel" class="panel report-inline-panel"><div class="panel-title"><div><h2>检验结果预览</h2><span id="reportInlineStatus">选择基地、机组和大修后自动生成</span></div></div><div id="reportInlinePreview" class="report-preview-content empty">尚未选择完整数据范围</div></section>');
  if($('#comparePanel'))$('#comparePanel').hidden=true;
  const form=$('#reportForm'),submit=form?.querySelector('button[type="submit"]');
  if(form&&submit&&!$('#reportAdvancedFields'))submit.insertAdjacentHTML('beforebegin','<section id="reportAdvancedFields" class="report-advanced-fields wide"><div class="report-fields-title"><b>检验与设备信息</b><span>可由检测数据自动带出，缺失项由报告人员补充</span></div><label>设备/部件编号<input id="reportComponentNo"></label><label>房间号<input id="reportRoom"></label><label>检验范围<input id="reportScope"></label><label>涡流仪型号<input id="reportInstrumentModel"></label><label>涡流仪出厂编号<input id="reportInstrumentSerial"></label><label>标定管编号<input id="reportCalibrationNo"></label><label>探头类型<input id="reportProbeType" value="BOBBIN"></label><label>探头型号<input id="reportProbeModel"></label><label>探头规格<input id="reportProbeSpec" value="Φ4.8 mm"></label><label>检验速度<input id="reportSpeed" value="250 mm/s"></label><label>采样率<input id="reportSampleRate" value="2000 点/秒"></label><label>检验频率<input id="reportFrequency" value="160、80、40、20 kHz"></label><label class="wide">检验程序/版次<input id="reportProcedure"></label></section>');
  if(form&&submit&&!$('#reportHeaderTable')){
    const scope=document.createElement('div');scope.className='report-scope-controls wide';scope.innerHTML='<b>数据范围</b>';
    ['reportSite','reportOutage'].forEach(id=>{const label=$('#'+id)?.closest('label');if(label)scope.append(label)});submit.before(scope);
    const grid=document.createElement('section');grid.id='reportHeaderTable';grid.className='report-header-table wide';
    const fields=[['reportComponentNo','设备/部件编号'],['reportTitle','涡流检验报告单（TH）'],['reportNo','报告单编码'],['reportPlant','电厂名称'],['reportUnit','机组'],['reportInspection','检查类型'],['reportComponent','设备/部件名称'],['reportSafety','安全等级'],['reportRoom','房间号'],['reportScope','检验范围'],['reportMaterial','材料'],['reportSize','尺寸'],['reportInstrumentModel','涡流仪型号'],['reportInstrumentSerial','涡流仪出厂编号'],['reportCalibrationNo','标定管编号'],['reportProbeType','探头类型'],['reportProbeModel','探头型号'],['reportProbeSpec','探头规格'],['reportSpeed','检验速度'],['reportSampleRate','采样率'],['reportFrequency','检验频率'],['reportProcedure','检验程序/版次']];
    fields.forEach(([id,title])=>{const control=$('#'+id),label=control?.closest('label');if(!label)return;[...label.childNodes].filter(node=>node.nodeType===Node.TEXT_NODE).forEach(node=>node.remove());label.className='report-header-cell';if(id==='reportTitle')label.classList.add('report-header-title');if(id==='reportSpeed')label.classList.add('report-header-speed');if(id==='reportSampleRate')label.classList.add('report-header-sample-rate');if(id==='reportFrequency')label.classList.add('report-header-frequency');if(id==='reportProcedure')label.classList.add('report-header-procedure');label.insertAdjacentHTML('afterbegin',`<span>${title}</span>`);grid.append(label)});
    submit.before(grid);$('#reportAdvancedFields')?.remove();$('#reportDirection')?.closest('label')?.remove();
    const defaults={reportComponentNo:'N1RIC000TY',reportTitle:'涡流检验报告单（TH）',reportNo:'N108ET632R04',reportPlant:'宁德核电厂',reportInspection:'P8/2024',reportComponent:'指套管',reportSafety:'2',reportRoom:'R141',reportScope:'管口至第3堆芯定位格架',reportMaterial:'Z5CND17-12',reportSize:'Φ8.6 × 1.7 mm',reportInstrumentModel:'TEDDY+A',reportInstrumentSerial:'ETbox8i-1026',reportCalibrationNo:'NDNP-NDI-RIC-01',reportProbeType:'BOBBIN',reportProbeModel:'TH048NAF25A',reportProbeSpec:'Φ4.8 mm',reportSpeed:'250 mm/s',reportSampleRate:'2000 点/秒',reportFrequency:'160、80、40、20（kHz）',reportProcedure:'ABW41299144CICA45SS/H版'};
    Object.entries(defaults).forEach(([id,value])=>{const control=$('#'+id);if(control&&!control.value.trim())control.value=value});
    $('#reportTitle').value='涡流检验报告单（TH）';
  }
  if(submit){submit.textContent='导出结果报告 Word';const actions=document.createElement('div');actions.className='report-form-actions wide';submit.before(actions);actions.append(submit);actions.insertAdjacentHTML('afterbegin','<span id="reportExportStatus">按当前筛选导出</span>')}
  const exportCompare=$('#exportCompareBtn');if(exportCompare)exportCompare.textContent='导出对比报告 Word';
  const comparisonTable=document.querySelector('.comparison-table');
  if(comparisonTable)comparisonTable.innerHTML='<caption>表 5　涡流检验结果比对表</caption><thead><tr><th rowspan="2">序号</th><th rowspan="2">通道编号</th><th rowspan="2">堆芯位置</th><th id="compareNewHeading" colspan="3">本次大修</th><th id="compareOldHeading" colspan="3">历史大修</th><th rowspan="2">结果比对</th></tr><tr><th>幅值（V）</th><th>磨损深度<br>（壁厚%）</th><th>磨损位置<br>（mm）</th><th>幅值（V）</th><th>磨损深度<br>（壁厚%）</th><th>磨损位置<br>（mm）</th></tr></thead><tbody id="compareRows"></tbody><tfoot><tr><td colspan="10">备注：结果比对栏内“R”表示此次显示为原有显示；“NI”表示为此次大修新发现的达到记录标准的显示。</td></tr></tfoot>';
  updateComparisonHeadings();
  $('#closeReportPreview').onclick=()=>$('#reportPreviewDialog').close();
}

function reportMetadataPayload(){return{plant:$('#reportPlant')?.value||'',report_no:$('#reportNo')?.value||'',inspection:$('#reportInspection')?.value||'',component:$('#reportComponent')?.value||'',safety:$('#reportSafety')?.value||'',direction:$('#reportDirection')?.value||'',material:$('#reportMaterial')?.value||'',size:$('#reportSize')?.value||'',title:$('#reportTitle')?.value||'',component_no:$('#reportComponentNo')?.value||'',room:$('#reportRoom')?.value||'',scope:$('#reportScope')?.value||'',instrument_model:$('#reportInstrumentModel')?.value||'',instrument_serial:$('#reportInstrumentSerial')?.value||'',calibration_no:$('#reportCalibrationNo')?.value||'',probe_type:$('#reportProbeType')?.value||'',probe_model:$('#reportProbeModel')?.value||'',probe_spec:$('#reportProbeSpec')?.value||'',speed:$('#reportSpeed')?.value||'',sample_rate:$('#reportSampleRate')?.value||'',frequency:$('#reportFrequency')?.value||'',procedure:$('#reportProcedure')?.value||''}}
function inspectionReportPayload(){
  const selected=state.items.filter(item=>state.selectedIds.has(item.id)),outages=new Set(selected.map(item=>item.outage)),units=new Set(selected.map(item=>Number(item.unit_id)));
  if(outages.size>1||units.size>1)throw new Error('结果报告只能包含同一次大修、同一机组的数据');
  const selectedRow=selected[0],outage=selectedRow?.outage||$('#reportOutage').value,unit=Number(selectedRow?.unit_id||$('#reportUnit').value);
  if(!outage||!unit)throw new Error('请选择或勾选同一次大修、同一机组的数据');
  if(selectedRow){$('#reportUnit').value=String(unit);refreshReportFilters();$('#reportOutage').value=outage}
  const metadata=reportMetadataPayload();
  return {outage,unit,metadata,finding_ids:selected.map(item=>item.id)};
}

function comparisonReportPayload(){const old=$('#oldOutage').value,newer=$('#newOutage').value,unit=Number($('#compareUnit').value);if(!old||!newer||!unit)throw new Error('请选择完整的对比条件');if(old===newer)throw new Error('请选择两个不同的大修批次');return{old,new:newer,unit}}
async function showReportPreview(payload){const data=await api('/api/report-preview',{method:'POST',body:JSON.stringify(payload)});$('#reportPreviewTitle').textContent=`${data.title} · ${data.rows} 条`;$('#reportPreviewContent').innerHTML=data.html;$('#reportPreviewDialog').showModal()}

installReportWorkflow();document.addEventListener('DOMContentLoaded',installReportWorkflow);
$('#reportForm').onsubmit=async event=>{event.preventDefault();const status=$('#reportExportStatus');try{const payload=inspectionReportPayload();status.textContent='正在生成 Word 报告...';const data=await api('/api/export-report',{method:'POST',body:JSON.stringify(payload)});status.innerHTML=`<a href="${data.download_url}">${data.filename}</a><small>${data.rows} 条记录</small>`;location.href=data.download_url;toast('结果报告 Word 已生成')}catch(error){status.textContent=error.message;toast(error.message)}};
$('#exportCompareBtn').onclick=async()=>{try{const data=await api('/api/export-comparison',{method:'POST',body:JSON.stringify(comparisonReportPayload())});location.href=data.download_url;toast(`对比报告 Word 已生成：R ${data.R} / NI ${data.NI}`)}catch(error){toast(error.message)}};

let reportPreviewTimer=0,reportPreviewRequest=0;
function reportFilterPayload(){const outage=$('#reportOutage').value,unit=Number($('#reportUnit').value);if(!outage||!unit)return null;return{kind:'inspection',outage,unit,metadata:reportMetadataPayload(),finding_ids:[]}}
async function refreshInlineReport(){const payload=reportFilterPayload(),host=$('#reportInlinePreview'),status=$('#reportInlineStatus'),request=++reportPreviewRequest;if(!host)return;if(!payload){host.className='report-preview-content empty';host.textContent='尚未选择完整数据范围';status.textContent='选择基地、机组和大修后自动生成';return}host.className='report-preview-content loading';host.textContent='正在读取当前大修检验结果...';try{const data=await api('/api/report-preview',{method:'POST',body:JSON.stringify(payload)});if(request!==reportPreviewRequest)return;host.className='report-preview-content';host.innerHTML=data.html;status.textContent=`${data.title} · ${data.rows} 条`}catch(error){if(request!==reportPreviewRequest)return;host.className='report-preview-content empty';host.textContent=error.message;status.textContent='预览生成失败'}}
function scheduleInlineReport(){clearTimeout(reportPreviewTimer);reportPreviewTimer=setTimeout(refreshInlineReport,220)}
$$('#reportForm input,#reportForm select').forEach(control=>{control.addEventListener('change',scheduleInlineReport);if(control.tagName==='INPUT')control.addEventListener('input',scheduleInlineReport)});document.querySelector('[data-view="reports"]')?.addEventListener('click',scheduleInlineReport);setTimeout(scheduleInlineReport,500);

const stateHeader=$('#stateRows')?.closest('table')?.querySelector('thead tr');
if(stateHeader&&!stateHeader.querySelector('.state-actions-head'))stateHeader.insertAdjacentHTML('beforeend','<th class="state-actions-head">操作</th>');

// Candidate reports are deliberately filtered in the dialog, while the server
// remains authoritative for parsing and duplicate/version validation.
(function installReportCandidateFilters(){
  const host=$('#reportOptions');if(!host)return;
  const toolbar=document.createElement('div');toolbar.className='report-option-filters';toolbar.innerHTML='<input id="reportOptionUnit" placeholder="筛选机组"><input id="reportOptionOutage" placeholder="筛选大修"><input id="reportOptionAnalyst" placeholder="筛选分析人员">';
  host.parentElement.insertBefore(toolbar,host);
  const filter=()=>{const terms=['reportOptionUnit','reportOptionOutage','reportOptionAnalyst'].map(id=>String($('#'+id)?.value||'').trim().toLowerCase());$$('#reportOptions .report-option').forEach(option=>{const text=option.textContent.toLowerCase();option.hidden=terms.some(term=>term&&!text.includes(term))})};
  toolbar.addEventListener('input',filter);new MutationObserver(filter).observe(host,{childList:true});
})();

